<?php
$input=static function(string $name,string $label,string $type='text',string $attrs=''):void{?><label class="bp-field" for="bp-<?=e($name)?>"><span><?=$label?></span><input id="bp-<?=e($name)?>" name="<?=e($name)?>" type="<?=e($type)?>" <?=$attrs?>></label><?php };
$select=static function(string $name,string $label,array $options,string $attrs=''):void{?><label class="bp-field" for="bp-<?=e($name)?>"><span><?=$label?></span><select id="bp-<?=e($name)?>" name="<?=e($name)?>" <?=$attrs?>><?php foreach($options as $value=>$text):?><option value="<?=e((string)$value)?>"><?=$text?></option><?php endforeach;?></select></label><?php };
$dimensions=static function(string $prefix,string $unit)use($input):void{?><div class="bp-three"><?php foreach(['width'=>'Largura','height'=>'Altura','depth'=>'Profundidade'] as $key=>$label)$input($prefix.'_'.$key,$label.' ('.$unit.')','number','min="0.01" max="10000" step="0.01" inputmode="decimal" placeholder="Ex.: '.($unit==='m'?'2,50':'30').'"'); ?></div><?php };
?>
